import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Application } from 'src/app/auth/Models/Application';
import { ApplicationDetails } from 'src/app/auth/Models/ApplicationDetails';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { SeekerService } from 'src/app/service/seeker/seeker.service';

@Component({
  selector: 'app-applicant',
  templateUrl: './applicant.component.html',
  styleUrls: ['./applicant.component.css']
})
export class ApplicantComponent {

        
          isLoggedIn = false;
          initials = '';
          profileRoute = '/';
        
          companyId!: number;
        
          company!: Company;
          jobs: Job[] = [];
          applications: Application[] = [];
          pendingApplications: Application[] = [];
          approvedAppplications: Application[] = [];
          applicant !: Application[];
          app !:ApplicationDetails;
        
          constructor(
            private compService: CompanyService,
            private appService: ApplicationService,
            private router: Router,
            private route: ActivatedRoute,
            private jobSeekerService: SeekerService
          ) {}
        
          ngOnInit(): void {
        
          const routeId = this.route.snapshot.paramMap.get('id');
        
          if (routeId) {
            // Public company profile
            this.companyId = Number(routeId);
          } else {
            // Logged-in company profile
            this.companyId = Number(localStorage.getItem('id'));
          }
        
          this.isLoggedIn = !!localStorage.getItem('token');
        
          if (this.isLoggedIn) {
        
            const role = localStorage.getItem('role');
            const loginId = Number(localStorage.getItem('id'));
        
            if (role === 'COMPANY') {
        
              this.profileRoute = '/company-dashboard';
        
              this.compService.getCompanyById(loginId).subscribe({
                next: (company: any) => {
                  if (company?.companyName) {
                    this.initials = company.companyName
                      .split(' ')
                      .map((x: string) => x.charAt(0))
                      .join('')
                      .substring(0, 2)
                      .toUpperCase();
                  }
                }
              });
        
            } else {
        
              this.profileRoute = '/jobseeker-dashboard';
        
              this.jobSeekerService.getSeekerById(loginId).subscribe({
                next: (user: any) => {
        
                  const name =
                    user.userName ??
                    `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();
        
                  if (name) {
                    this.initials = name
                      .split(' ')
                      .map((x: string) => x.charAt(0))
                      .join('')
                      .substring(0, 2)
                      .toUpperCase();
                  }
                }
              });
            }
          }
        
          this.getCompanyById();
          this.getJobsByCompany();
          this.getApplicantByJob();
          this.getApplicantById();
        }
          getCompanyById() {
            this.compService.getCompanyById(this.companyId).subscribe(
              res => this.company = res
            );
          }
        
          getJobsByCompany() {
            this.compService.getJobsByCompany(this.companyId).subscribe(
              res => this.jobs = res
            );
          }
        
          getApplicantsByCompany() {
            this.appService.getApplicantsByCompany(this.companyId).subscribe(
              res => this.applications = res
            );
          }
        
          getPendingApplications() {
            this.appService.getPendindApplicants(this.companyId).subscribe(
              res => this.pendingApplications = res
            );
          }
        
          getHiredApplicants() {
            this.appService.getHiredApplicants(this.companyId).subscribe(
              res => this.approvedAppplications = res
            );
          }

          getApplicantByJob(){
            this.appService.getApplicationByJob(Number(this.route.snapshot.paramMap.get('jobId'))).subscribe(
              res =>
                this.applicant = res
            )
          }

          getApplicantById(){
            this.appService.getApplicationById(Number(this.route.snapshot.paramMap.get('appId'))).subscribe(
              res =>
                this.app = res
            )
          }
        
          logout(): void {
            localStorage.clear();
            this.router.navigate(['/']);
            alert('Continue to Logout?');
          }
        
      
      
    
    
  
  

}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Applicant Detail · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav app">
  <div class="wrap">
    <a routerLink="/" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a routerLink="../company-dashboard" >Dashboard</a>
      <a routerLink="../company-post-job">Post a Job</a>
      <a routerLink="/company-manage-jobs">Manage Jobs</a>
      <a routerLink="/company-applicants" class="active">Applicants</a>
      <a routerLink="/profile-company">Company Profile</a>
    </nav>
    <div class="avatar">{{initials}}</div>
  </div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a routerLink="/company-dashboard" ><span class="dot"></span>Dashboard</a>
    <a routerLink="/profile-company"><span class="dot"></span>Company Profile</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Hiring</span>
    <a routerLink="/company-post-job"><span class="dot"></span>Post a Job</a>
    <a routerLink="/company-manage-jobs"><span class="dot"></span>Manage Jobs</a>
    <a routerLink="/company-applicants" class="active"><span class="dot"></span>Applicants</a>
  </div>
</aside>
<main class="main">

<div class="breadcrumb">Applicants / <span>{{app.jobSeekerName}}</span></div>
<div class="card-row" style="grid-template-columns:1fr 2fr;align-items:start;">
  <div class="card">
    <div class="avatar" style="width:52px;height:52px;font-size:16px;margin-bottom:12px;" *ngIf="app">{{app.jobSeekerName.charAt(0)}}</div>
    <h3 style="font-size:17px;">{{app.jobSeekerName}}</h3>
    <p class="muted" style="font-size:13px;">{{app.location}}</p>
    <p class="muted" style="font-size:13px;">{{app.email}}</p>
    <a href="#" class="btn btn-secondary btn-block" style="margin-top:16px;">Open resume PDF</a>
  </div>
  <div class="card">
    <div style="display:flex;justify-content:space-between;">
      <h3 style="font-size:15px;">Application for {{app.jobTitle}}</h3>
      <span class="chip " [ngClass]="{'chip-rejected':app.status === 'REJECTED','chip-pending' : app.status === 'PENDING','chip-open' : app.status === 'APPROVED'}">{{app.status}}</span>
    </div>
    <p class="muted" style="font-size:13px;margin-top:4px;">Applied on {{app.appliedDate}}</p>
    <div style="margin-top:18px;height:220px;border:1px dashed var(--line);border-radius:8px;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:13px;">Resume preview (PDF)</div>
    <a [routerLink]="['/company/review',app.applicationId]" class="btn btn-primary" style="margin-top:16px;">Review application</a>
  </div>
</div>

</main>
</div>
</div>
</body>
</html>
